    59	public enum Xzn53Status {
    60	    PENDING {
    61	        @Override
    62	        public boolean canTransitionTo(Xzn53Status nextStatus) {
    63	            return nextStatus == SHIPPED || nextStatus == CANCELED;
    64	        }
    65	    },
    66	    SHIPPED {
    67	        @Override
    68	        public boolean canTransitionTo(Xzn53Status nextStatus) {
    69	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
    70	        }
    71	    },
    72	    IN_TRANSIT {
    73	        @Override
    74	        public boolean canTransitionTo(Xzn53Status nextStatus) {
    75	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
    76	                    || nextStatus == DELIVERED;
    77	        }
    78	    },
    79	    OUT_FOR_DELIVERY {
    80	        @Override
    81	        public boolean canTransitionTo(Xzn53Status nextStatus) {
    82	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
    83	        }
    84	    },
    85	    DELIVERED {
    86	        @Override
    87	        public boolean canTransitionTo(Xzn53Status nextStatus) {
    88	            return false;
    89	        }
    90	    },
    91	    RETURNED {
    92	        @Override
    93	        public boolean canTransitionTo(Xzn53Status nextStatus) {
    94	            return nextStatus == CANCELED;
    95	        }
    96	    },
    97	    CANCELED {
    98	        @Override
    99	        public boolean canTransitionTo(Xzn53Status nextStatus) {
   100	            return false;
   101	        }
   102	    },
   103	    DELAYED {
   104	        @Override
   105	        public boolean canTransitionTo(Xzn53Status nextStatus) {
   106	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
   107	        }
   108	    },
   109	    FAILED_DELIVERY {
