186	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
187	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
188	
189	        try {
190	
191	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
192	            Document doc = Jsoup.connect(url).get();
193	
194	            Elements rows = doc.select("tbody#statusDetail tr");
195	            if (rows.isEmpty()) {
196	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
197	                throw new Xzn53Exception(
198	                        Xzn53ErrorCode.TRACKING_HTML_PARSE_ERROR,
199	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
200	                );
201	            }
202	
203	            String status = rows.last().select("td").get(4).text();
204	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
205	            return status;
206	
207	        } catch (Exception e) {
208	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
209	
210	            if (e instanceof Xzn53Exception) {
211	                throw e;
212	            }
213	
214	            throw new Xzn53Exception(
215	                    Xzn53ErrorCode.TRACKING_HTML_PARSE_ERROR,
216	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
217	                    e
218	            );
219	        }
220	    }
